where
    F: Fn(&Message<Value>) -> bool,
{
    q.retain(|m| !drop_if(m));
}

fn settle(nodes: &mut [Node], q: &mut Vec<Message<Value>>) {
    for _ in 0..2000 {
        collect(nodes, q);
        if q.is_empty() {
            return;
        }
